import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'hub-collection-card-1-label';

  // Atlas region
  const region = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;
  const height = 0.5;
  const width = height * aspect;

  const geo = new PlaneGeometry(width, height);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
    depthWrite: false,
    toneMapped: false,
  });

  const plane = new Mesh(geo, mat);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // Load atlas texture and map UVs to the region
  const texUrl = config.imageUrl;
  let cleanupTex = () => {};
  if (texUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      const imgW = tex.image?.width || region.w;
      const imgH = tex.image?.height || region.h;
      // Assume flipY default (true): v=0 at bottom of image
      const repeatX = region.w / imgW;
      const repeatY = region.h / imgH;
      const offsetX = region.x / imgW;
      const offsetY = 1 - (region.y + region.h) / imgH;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.repeat.set(repeatX, repeatY);
      tex.offset.set(offsetX, offsetY);
      tex.needsUpdate = true;
      mat.map = tex;
      mat.opacity = 1;
      mat.needsUpdate = true;
      cleanupTex = () => { tex.dispose?.(); };
    }).catch(() => {});
  } else {
    mat.opacity = 1;
  }

  // Sprite-style billboard: plane already faces +z toward camera at z=10
  // Apply scene placement
  const pos = config.scenePosition ?? [-3.2, 1, 0.06];
  group.position.set(pos[0], pos[1], pos[2]);
  const rot = config.sceneRotation ?? [0, 0, 0];
  group.rotation.set(rot[0], rot[1], rot[2]);
  const scl = config.sceneScale ?? [1, 1, 1];
  group.scale.set(scl[0], scl[1], scl[2]);

  // Entrance: fade-up
  const tl = gsap.timeline();
  tl.fromTo(group.position, { y: pos[1] + 0.2 }, { y: pos[1], duration: 0.6, ease: 'power3.out' }, 0);
  tl.fromTo(mat, { opacity: 0 }, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
    cleanupTex();
  };

  return group;
}
